#include "network.hpp"
#include <algorithm>
#include <cmath>
#include <limits>
namespace worldforge::net {
namespace {
void put(std::vector<uint8_t>& b,uint64_t x,int n){for(int i=0;i<n;++i)b.push_back(uint8_t(x>>(8*i)));}
bool get(const std::vector<uint8_t>& b,size_t& i,uint64_t& x,int n){if(n<0||i+n>b.size())return false;x=0;for(int j=0;j<n;++j)x|=uint64_t(b[i++])<<(8*j);return true;}
void playerPut(std::vector<uint8_t>& b,const Player&p){put(b,p.id,4);put(b,uint32_t(p.x),4);put(b,uint32_t(p.z),4);put(b,uint32_t(p.vx),4);put(b,uint32_t(p.vz),4);}
bool playerGet(const std::vector<uint8_t>& b,size_t&i,Player&p){uint64_t x; if(!get(b,i,x,4))return false;p.id=uint32_t(x);if(!get(b,i,x,4))return false;p.x=int32_t(uint32_t(x));if(!get(b,i,x,4))return false;p.z=int32_t(uint32_t(x));if(!get(b,i,x,4))return false;p.vx=int32_t(uint32_t(x));if(!get(b,i,x,4))return false;p.vz=int32_t(uint32_t(x));return true;}
uint64_t mix(uint64_t h,uint32_t v){for(int i=0;i<4;++i){h^=uint8_t(v>>(8*i));h*=1099511628211ull;}return h;}
}
uint64_t checksum(const State&s){uint64_t h=14695981039346656037ull;h=mix(h,s.tick);auto ps=s.players;std::sort(ps.begin(),ps.end(),[](auto&a,auto&b){return a.id<b.id;});for(auto&p:ps){h=mix(h,p.id);h=mix(h,uint32_t(p.x));h=mix(h,uint32_t(p.z));h=mix(h,uint32_t(p.vx));h=mix(h,uint32_t(p.vz));}return h;}
bool validate(const Input&i){return i.player<1024&&i.steer>=-1000&&i.steer<=1000&&i.throttle<=100&&i.brake<=100;}
void advance(State&s,const std::vector<Input>& in){auto sorted=in;std::sort(sorted.begin(),sorted.end(),[](auto&a,auto&b){return a.player<b.player;});for(auto&i:sorted){if(!validate(i)||i.tick!=s.tick)continue;auto p=std::find_if(s.players.begin(),s.players.end(),[&](auto&p){return p.id==i.player;});if(p==s.players.end())continue;int64_t ax=int64_t(i.steer)/10;int64_t az=int64_t(i.throttle)*2-int64_t(i.brake)*3;p->vx=int32_t(std::clamp(int64_t(p->vx)*95/100+ax,int64_t(-5000),int64_t(5000)));p->vz=int32_t(std::clamp(int64_t(p->vz)*95/100+az,int64_t(-5000),int64_t(5000)));}for(auto&p:s.players){p.x=int32_t(std::clamp(int64_t(p.x)+p.vx,int64_t(INT32_MIN),int64_t(INT32_MAX)));p.z=int32_t(std::clamp(int64_t(p.z)+p.vz,int64_t(INT32_MIN),int64_t(INT32_MAX)));}++s.tick;}
std::vector<uint8_t> encodeInput(const Input&i){std::vector<uint8_t>b;put(b,i.tick,4);put(b,i.player,4);put(b,uint16_t(i.steer),2);put(b,i.throttle,1);put(b,i.brake,1);return b;}
std::optional<Input> decodeInput(const std::vector<uint8_t>&b){if(b.size()!=12)return {};size_t k=0;uint64_t x;Input i;get(b,k,x,4);i.tick=uint32_t(x);get(b,k,x,4);i.player=uint32_t(x);get(b,k,x,2);i.steer=int16_t(uint16_t(x));get(b,k,x,1);i.throttle=uint8_t(x);get(b,k,x,1);i.brake=uint8_t(x);if(!validate(i))return {};return i;}
Snapshot snapshot(const State&s){return {s.tick,checksum(s),s.players};}
std::vector<uint8_t> encodeSnapshot(const Snapshot&s){std::vector<uint8_t>b;put(b,s.tick,4);put(b,s.checksum,8);put(b,s.players.size(),2);for(auto&p:s.players)playerPut(b,p);return b;}
std::optional<Snapshot> decodeSnapshot(const std::vector<uint8_t>&b){size_t k=0;uint64_t x;Snapshot s;if(!get(b,k,x,4))return {};s.tick=uint32_t(x);if(!get(b,k,x,8))return {};s.checksum=x;if(!get(b,k,x,2)||x>1024||b.size()!=14+x*20)return {};for(size_t j=0,n=size_t(x);j<n;++j){Player p;if(!playerGet(b,k,p))return {};s.players.push_back(p);}State state{s.tick,s.players};if(checksum(state)!=s.checksum)return {};return s;}
std::vector<uint8_t> encodePacket(const Packet&p){std::vector<uint8_t>b;put(b,0x5746,2);put(b,1,1);put(b,p.sequence,2);put(b,p.ack,2);put(b,p.ackBits,4);put(b,p.payload.size(),2);b.insert(b.end(),p.payload.begin(),p.payload.end());return b;}
std::optional<Packet> decodePacket(const std::vector<uint8_t>&b){size_t k=0;uint64_t x;if(!get(b,k,x,2)||x!=0x5746||!get(b,k,x,1)||x!=1)return {};Packet p;if(!get(b,k,x,2))return {};p.sequence=uint16_t(x);if(!get(b,k,x,2))return {};p.ack=uint16_t(x);if(!get(b,k,x,4))return {};p.ackBits=uint32_t(x);if(!get(b,k,x,2)||x>1200||b.size()!=13+x)return {};p.payload.assign(b.begin()+13,b.end());return p;}
bool sequenceNewer(uint16_t a,uint16_t b){return a!=b&&uint16_t(a-b)<32768;}
bool AckWindow::receive(uint16_t s){if(!initialized){initialized=true;latest=s;return true;}if(s==latest)return false;if(sequenceNewer(s,latest)){uint16_t delta=uint16_t(s-latest);bits=delta>32?0:((bits<<delta)|(1u<<(delta-1)));latest=s;return true;}uint16_t d=uint16_t(latest-s);if(d>32)return false;uint32_t mask=1u<<(d-1);bool fresh=(bits&mask)==0;bits|=mask;return fresh;}
bool AckWindow::acknowledged(uint16_t s)const{if(!initialized)return false;if(s==latest)return true;uint16_t d=uint16_t(latest-s);return d>=1&&d<=32&&(bits&(1u<<(d-1)))!=0;}
bool InputBuffer::enqueue(Input i){if(!validate(i))return false;auto& v=pending[i.tick];if(v.size()>=1024||std::any_of(v.begin(),v.end(),[&](auto&a){return a.player==i.player;}))return false;v.push_back(i);return true;}
std::vector<Input> InputBuffer::take(uint32_t tick){auto it=pending.find(tick);if(it==pending.end())return {};auto out=std::move(it->second);pending.erase(it);std::sort(out.begin(),out.end(),[](auto&a,auto&b){return a.player<b.player;});return out;}
State Replay::play(uint32_t end)const{State s=initial;InputBuffer b;for(auto&i:inputs)if(i.tick>=s.tick&&i.tick<end)b.enqueue(i);while(s.tick<end)advance(s,b.take(s.tick));return s;}
void Reconciler::step(const std::vector<Input>&in){history[predicted.tick]=predicted;inputs[predicted.tick]=in;advance(predicted,in);while(history.size()>256){auto t=history.begin()->first;history.erase(t);inputs.erase(t);}}
bool Reconciler::reconcile(const Snapshot&s){State authoritative{s.tick,s.players};if(checksum(authoritative)!=s.checksum||s.tick>predicted.tick)return false;auto it=history.find(s.tick);if(it==history.end())return false;bool changed=checksum(it->second)!=s.checksum;if(changed){uint32_t end=predicted.tick;predicted=authoritative;while(predicted.tick<end){auto p=inputs.find(predicted.tick);advance(predicted,p==inputs.end()?std::vector<Input>{}:p->second);}}return changed;}
std::vector<uint8_t> encodeDelta(const Snapshot&a,const Snapshot&b){std::vector<uint8_t>out;put(out,a.tick,4);put(out,b.tick,4);put(out,b.checksum,8);std::vector<Player>changed;for(auto&p:b.players){auto it=std::find_if(a.players.begin(),a.players.end(),[&](auto&q){return p.id==q.id;});if(it==a.players.end()||it->x!=p.x||it->z!=p.z||it->vx!=p.vx||it->vz!=p.vz)changed.push_back(p);}put(out,b.players.size(),2);put(out,changed.size(),2);for(auto&p:changed)playerPut(out,p);return out;}
std::optional<Snapshot> applyDelta(const Snapshot&a,const std::vector<uint8_t>&b){size_t k=0;uint64_t x;if(!get(b,k,x,4)||x!=a.tick)return {};Snapshot s=a;if(!get(b,k,x,4))return {};s.tick=uint32_t(x);if(!get(b,k,x,8))return {};s.checksum=x;if(!get(b,k,x,2)||x>1024)return {};size_t total=size_t(x);if(!get(b,k,x,2)||x>1024||b.size()!=20+x*20)return {};for(size_t j=0,n=size_t(x);j<n;++j){Player p;if(!playerGet(b,k,p))return {};auto it=std::find_if(s.players.begin(),s.players.end(),[&](auto&q){return q.id==p.id;});if(it==s.players.end())s.players.push_back(p);else *it=p;}if(s.players.size()!=total||checksum(State{s.tick,s.players})!=s.checksum)return {};return s;}
Interpolated interpolate(const Player&a,const Player&b,double t){t=std::isfinite(t)?std::clamp(t,0.,1.):0.;return {a.x+(b.x-a.x)*t,a.z+(b.z-a.z)*t};}
bool RateLimiter::allow(uint32_t tick){if(tick<start||tick-start>=window){start=tick;count=0;}if(count>=limit)return false;++count;return true;}
}
